// Helper to convert Excel serial date to ISO string
function excelDateToISO(serial) {
  if (!serial || isNaN(serial)) return '';
  const date = new Date((serial - 25569) * 86400 * 1000);
  return date.toISOString();
}

// Clean email — strip markdown link format [email](mailto:email)
function cleanEmail(val) {
  if (!val) return '';
  const match = val.match(/\[([^\]]+)\]\(mailto:[^\)]+\)/);
  return match ? match[1] : val;
}

// Validate required fields (using ACTUAL column names from your sheet)
if (!row['Supplier URL'] || !row['Product / Item'] || !row['Quantity'] || !row['Our Budget ($)']) {
  throw new Error('Missing required fields: Supplier URL, Product / Item, Quantity, or Our Budget ($)');
}

return [{
  json: {
    rowId:        row['Row ID'] || Date.now().toString(),
    supplierName: row['Supplier Name'] || 'Unknown Supplier',
    supplierUrl:  row['Supplier URL'],
    supplierEmail: cleanEmail(row['Supplier Email']),
    product:      row['Product / Item'],
    quantity:     row['Quantity'],
    budget:       row['Our Budget ($)'],
    listedPrice:  row['Listed Price ($)'] || row['Our Budget ($)'],
    requestDate:  excelDateToISO(row['Request Date']),
    messageSentAt: excelDateToISO(row['Message Sent At']),
    retrySentAt:  excelDateToISO(row['Retry Sent At']),
    finalPrice:   row['Final Price ($)'] || null,
    status:       row['Status'] || 'Pending',
    angleTried:   row['Angle Tried'] || '',
    timestamp:    new Date().toISOString()
  }
}];
})();
return { body: __unwrap(__result) };

